CREATE OR REPLACE FUNCTION public.can_read_staff_profile(_user uuid, _target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user=_target OR public.is_super_admin(_user) OR public.has_role(_user,'admin') OR EXISTS (SELECT 1 FROM public.department_memberships m WHERE m.user_id=_target AND public.manages_department(_user,m.department_id)) $$;
CREATE OR REPLACE FUNCTION public.add_department_teacher(_email text, _department uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Only the super admin can grant permissions'; END IF; SELECT id INTO target FROM public.profiles WHERE lower(email)=lower(trim(_email)); IF target IS NULL THEN RAISE EXCEPTION 'An existing registered staff account is required'; END IF; PERFORM public.set_department_access(target,_department,'teacher'); END $$;
CREATE OR REPLACE FUNCTION public.set_attendance_grants(_target uuid, _take boolean, _edit boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Only the super admin can grant permissions'; END IF; UPDATE public.department_memberships SET can_take=_take,can_edit=_edit WHERE user_id=_target; IF NOT FOUND THEN RAISE EXCEPTION 'Assign a department first'; END IF; END $$;
REVOKE ALL ON FUNCTION public.set_attendance_grants(uuid,boolean,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_attendance_grants(uuid,boolean,boolean) TO authenticated;
GRANT SELECT ON public.super_admins TO authenticated;
GRANT ALL ON public.super_admins TO service_role;